#!/usr/bin/env bash
# Applies the RQ2 scenarios (../scenarios/<platform>/{base,seeds}.yaml) to the replay API
# server, plus the objects that the platforms' controllers or installers create on minikube
# (the "shim"). Every shim object is listed below with the controller it stands in for.
#   - namespaces created by the installs (argocd) and by Kargo Projects (kp-kargo-1, kp-kargo-2);
#   - Argo CD: the Applications generated by the three ApplicationSets that match something,
#     owned by their ApplicationSet (as the applicationset-controller does);
#   - cert-manager: one CertificateRequest per Certificate revision, owned by the Certificate,
#     including the rotation of Certificate api from ci-old-ca to ci-new-ca (post.sh);
#   - KubeVela: Application a3, applied by post.sh once the pinned DefinitionRevision exists;
#   - CloudNativePG: post.sh's self-referencing Pooler is NOT created, because the CNPG
#     admission webhook rejects it on minikube (row blocked-upstream).
set -euo pipefail
source "$(dirname "$0")/env.sh"
S="$EVAL/scenarios"
apply() { kubectl apply --server-side --force-conflicts -f "$@" >/dev/null; }

for ns in argocd kp-kargo-1 kp-kargo-2; do
  kubectl create namespace "$ns" --dry-run=client -o yaml | apply -
done
kubectl label namespace kp-kargo-1 kp-kargo-2 kargo.akuity.io/project=true --overwrite >/dev/null

for p in argocd capi cert-manager cnpg crossplane external-secrets flux kargo kubevela; do
  [[ -f "$S/$p/projects.yaml" ]] && apply "$S/$p/projects.yaml"
  for f in base.yaml seeds.yaml; do [[ -f "$S/$p/$f" ]] && apply "$S/$p/$f"; done
done

# --- Argo CD applicationset-controller
appset_app() { # <appset> <app name>
  local uid; uid="$(kubectl -n argocd get applicationset "$1" -o jsonpath='{.metadata.uid}')"
  apply - <<YAML
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  name: $2
  namespace: argocd
  ownerReferences:
    - {apiVersion: argoproj.io/v1alpha1, kind: ApplicationSet, name: $1, uid: $uid, controller: true, blockOwnerDeletion: true}
spec:
  project: team-appset
  source: {repoURL: "https://github.com/argoproj/argocd-example-apps.git", path: guestbook, targetRevision: HEAD}
  destination: {server: https://kubernetes.default.svc, namespace: kp-argo-apps}
YAML
}
appset_app as-list-2 as-list-2-one
appset_app as-list-2 as-list-2-two
appset_app as-list-1 as-list-1-solo
appset_app as-cluster-all as-cluster-all-in-cluster

# --- cert-manager: the Certificate of post.sh, then one CertificateRequest per revision
apply - <<'YAML'
apiVersion: cert-manager.io/v1
kind: Certificate
metadata: {name: api, namespace: kp-certs}
spec:
  secretName: api-tls
  dnsNames: ["api.kp-certs.svc"]
  revisionHistoryLimit: 3
  issuerRef: {name: ci-new-ca, kind: ClusterIssuer}
YAML
csr="$(openssl req -new -newkey rsa:2048 -nodes -keyout /dev/null -subj /CN=replay 2>/dev/null | base64 -w0)"
cert_request() { # <certificate> <revision> <issuer json>
  local uid; uid="$(kubectl -n kp-certs get certificate "$1" -o jsonpath='{.metadata.uid}')"
  apply - <<YAML
apiVersion: cert-manager.io/v1
kind: CertificateRequest
metadata:
  name: $1-$2
  namespace: kp-certs
  annotations: {cert-manager.io/certificate-name: $1, cert-manager.io/certificate-revision: "$2"}
  ownerReferences:
    - {apiVersion: cert-manager.io/v1, kind: Certificate, name: $1, uid: $uid, controller: true, blockOwnerDeletion: true}
spec:
  request: $csr
  issuerRef: $3
YAML
}
for c in $(kubectl -n kp-certs get certificates -o jsonpath='{.items[*].metadata.name}'); do
  [[ $c == api ]] && continue
  cert_request "$c" 1 "$(kubectl -n kp-certs get certificate "$c" -o jsonpath='{.spec.issuerRef}')"
done
cert_request api 1 '{"name": "ci-old-ca", "kind": "ClusterIssuer"}'
cert_request api 2 '{"name": "ci-new-ca", "kind": "ClusterIssuer"}'
kubectl -n kp-certs patch certificate api --subresource=status --type=merge -p '{"status":{"revision":2}}' >/dev/null

# --- KubeVela post.sh
apply - <<'YAML'
apiVersion: core.oam.dev/v1beta1
kind: Application
metadata: {name: a3, namespace: kp-vela-a}
spec:
  components:
    - name: pinned
      type: kp-versioned@v1
YAML
echo "scenarios applied: $(kubectl get ns --no-headers | grep -c '^kp-') kp-* namespaces"
